edits.after:
reg [1:0] 		bsel;

// Tag the read launched at the previous registered SRAM address edge.
reg wb_read_pending;
reg [1:0] wb_read_lane;

edits.before:
if (bsel == 2'b01) wb_rdt[7:0]   <= i_sram_rdata;
if (bsel == 2'b10) wb_rdt[15:8]  <= i_sram_rdata;
if (bsel == 2'b11) wb_rdt[23:16] <= i_sram_rdata;

edits.after:
wb_read_pending <= wb_en & !i_wb_we;
wb_read_lane <= bsel;
if (wb_read_pending) begin
   if (wb_read_lane == 2'b00) wb_rdt[7:0]   <= i_sram_rdata;
   if (wb_read_lane == 2'b01) wb_rdt[15:8]  <= i_sram_rdata;
   if (wb_read_lane == 2'b10) wb_rdt[23:16] <= i_sram_rdata;
end
